import pyomo.environ as pyo

DATA = {
    "num_centers": 8,
    "num_stores": 8,
    "opening_cost": {
        1: 151000, 2: 192000, 3: 114000, 4: 171000,
        5: 160000, 6: 120000, 7: 182000, 8: 186000,
    },
    "transport_cost": {
        1: {1: 3, 2: 3, 3: 5, 4: 4, 5: 3, 6: 5, 7: 2, 8: 4},
        2: {1: 2, 2: 4, 3: 5, 4: 1, 5: 4, 6: 2, 7: 5, 8: 4},
        3: {1: 1, 2: 1, 3: 3, 4: 3, 5: 2, 6: 4, 7: 4, 8: 3},
        4: {1: 4, 2: 4, 3: 1, 4: 3, 5: 5, 6: 3, 7: 5, 8: 1},
        5: {1: 2, 2: 4, 3: 1, 4: 4, 5: 2, 6: 2, 7: 1, 8: 2},
        6: {1: 5, 2: 2, 3: 4, 4: 4, 5: 4, 6: 4, 7: 5, 8: 3},
        7: {1: 1, 2: 4, 3: 2, 4: 4, 5: 2, 6: 2, 7: 4, 8: 5},
        8: {1: 2, 2: 2, 3: 4, 4: 2, 5: 2, 6: 4, 7: 4, 8: 1},
    },
    "demand": {
        1: 695, 2: 737, 3: 452, 4: 616,
        5: 587, 6: 779, 7: 892, 8: 440,
    },
    "capacity": {
        1: 1980, 2: 814, 3: 864, 4: 1320,
        5: 1952, 6: 1447, 7: 1886, 8: 1962,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.I = pyo.RangeSet(1, d["num_centers"])
    model.J = pyo.RangeSet(1, d["num_stores"])

    model.open_center = pyo.Var(model.I, within=pyo.Binary)
    model.ship = pyo.Var(model.I, model.J, within=pyo.NonNegativeReals)

    def obj_rule(m):
        open_cost = sum(d["opening_cost"][i] * m.open_center[i] for i in m.I)
        transport_cost = sum(
            d["transport_cost"][i][j] * m.ship[i, j]
            for i in m.I for j in m.J
        )
        return open_cost + transport_cost

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def demand_rule(m, j):
        return sum(m.ship[i, j] for i in m.I) >= d["demand"][j]

    model.demand_satisfied = pyo.Constraint(model.J, rule=demand_rule)

    def capacity_rule(m, i):
        return sum(m.ship[i, j] for j in m.J) <= d["capacity"][i] * m.open_center[i]

    model.capacity_limit = pyo.Constraint(model.I, rule=capacity_rule)

    return model
